    { label: 'کاربران', icon: <PeopleIcon />, key: 'users', color: '#10b981', desc: 'مدیریت حساب‌های کاربری و نقش‌های آن‌ها' },
    { label: 'نقش‌ها و دسترسی', icon: <SecurityIcon />, key: 'roles', color: '#f59e0b', desc: 'تعریف سطوح دسترسی و مجوزهای هر نقش' },
    { label: 'درون‌ریزی اکسل', icon: <UploadFileIcon />, key: 'import', color: '#14b8a6', desc: 'بارگذاری گروهی داده‌ها از فایل اکسل' },
    { label: 'ظاهر', icon: <PaletteIcon />, key: 'appearance', color: '#8b5cf6', desc: 'شخصی‌سازی تم، مد نمایش و رنگ نئونی' },
  ];

  const active = tabs[tabIndex];

  return (
    <Box>
      {/* Glass header */}
      <Paper sx={{
        mb: 3, p: 2.5,
        display: 'flex', alignItems: 'center', gap: 2,
        background: 'linear-gradient(135deg, rgba(99,102,241,0.12), rgba(236,72,153,0.05))',
        border: '1px solid rgba(99,102,241,0.2)',
        backdropFilter: 'blur(20px)', WebkitBackdropFilter: 'blur(20px)',
        borderRadius: 3,
      }}>
        <Avatar sx={{
          width: 56, height: 56,
          background: 'linear-gradient(135deg, #6366f1, #ec4899)',
          boxShadow: '0 6px 20px rgba(99,102,241,0.4)',
        }}>
          <TuneIcon sx={{ fontSize: 28, color: '#fff' }} />
        </Avatar>
        <Box>
          <Typography variant="h5" fontWeight={800}>{t('nav.settings')}</Typography>
          <Typography variant="body2" color="textSecondary">تنظیمات سیستم، مدیریت کاربران و ابزارها</Typography>
        </Box>
      </Paper>

      {/* Glass container with colored tabs */}
      <Paper sx={{
        overflow: 'hidden',
        background: 'linear-gradient(135deg, rgba(255,255,255,0.55), rgba(255,255,255,0.3))',
        backdropFilter: 'blur(20px)', WebkitBackdropFilter: 'blur(20px)',
        border: '1px solid rgba(255,255,255,0.4)',
        borderRadius: 3,
      }}>
        <Tabs
          value={tabIndex} onChange={(e, v) => setTabIndex(v)}
          variant="scrollable" scrollButtons="auto"
          sx={{ borderBottom: '1px solid rgba(255,255,255,0.4)', px: 2 }}
        >
          {tabs.map((tab, i) => (
            <Tab
              key={tab.key}
              label={tab.label}
              sx={{
                fontWeight: 600,
                py: 1.75,
                color: tabIndex === i ? tab.color : 'text.secondary',
              }}
            />
          ))}
        </Tabs>
        <Box sx={{ p: 3 }}>
          <Paper sx={{
            mb: 2, px: 1.5, py: 1,
            background: `linear-gradient(135deg, ${active.color}0d, ${active.color}04)`,
            border: `1px solid ${active.color}20`,
            borderRadius: 2,
          }}>
            <Typography variant="body2" sx={{ color: active.color, fontWeight: 600 }}>{active.desc}</Typography>
          </Paper>

          {tabIndex === 0 && <GeneralSettingsTab />}
          {tabIndex === 1 && <UserManagementTab />}
          {tabIndex === 2 && <RolesTab />}
          {tabIndex === 3 && <ImportTab />}
          {tabIndex === 4 && <AppearanceTab />}
        </Box>
      </Paper>
    </Box>
  );
};

export default Settings;
